import{_ as l,I as t,c as n,o as a,a3 as e,b as o,w as s,a as h,J as d,a4 as E}from"./chunks/framework.MI-M1z4O.js";const m=JSON.parse('{"title":"災害復旧（DR）および高可用性設計","description":"エンタープライズ環境でデータ整合性を保証し、RTO 15分以内のシステム復旧を達成するための高可用性（HA）および災害復旧（DR）ガイド","frontmatter":{"title":"災害復旧（DR）および高可用性設計","shortTitle":"災害復旧 & DR","category":"インフラ & セキュリティ","sort":5,"description":"エンタープライズ環境でデータ整合性を保証し、RTO 15分以内のシステム復旧を達成するための高可用性（HA）および災害復旧（DR）ガイド","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/infra/disaster-recovery"}]]},"headers":[],"relativePath":"ja/infra/disaster-recovery.md","filePath":"ja/infra/disaster-recovery.md","lastUpdated":1795293539000}'),p={name:"ja/infra/disaster-recovery.md"};function c(k,i,g,A,B,_){const r=t("Mermaid");return a(),n("div",null,[i[1]||(i[1]=e('<h1 id="災害復旧-dr-および高可用性設計" tabindex="-1">災害復旧（DR）および高可用性設計 <a class="header-anchor" href="#災害復旧-dr-および高可用性設計" aria-label="Permalink to “災害復旧（DR）および高可用性設計”">​</a></h1><h2 id="_1-概要および復旧目標基準" tabindex="-1">1. 概要および復旧目標基準 <a class="header-anchor" href="#_1-概要および復旧目標基準" aria-label="Permalink to “1. 概要および復旧目標基準”">​</a></h2><p>SyncSeriesは、データ損失が致命的となる金融、製造、公共サービスを安定的に支援するため、明確な復旧目標指標（RPO、RTO）を定義し、マルチリージョンおよび冗長化インフラを運用します。</p><ul><li><strong>RPO（Recovery Point Objective - 目標復旧時点）</strong>: <strong>0分</strong>（同期レプリケーション環境基準）／最大1分以内（非同期クロスリージョンレプリケーション基準）。</li><li><strong>RTO（Recovery Time Objective - 目標復旧時間）</strong>: <strong>15分以内</strong>（主センター障害発生時、副センターへのトラフィック切り替え完了基準）。</li></ul>',4)),(a(),o(E,null,{default:s(()=>[d(r,{id:"mermaid-21",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20PrimaryDC%20%5B%22%E4%B8%BB%E3%83%87%E3%83%BC%E3%82%BF%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%20(Active)%22%5D%0A%20%20%20%20%20%20%20%20K8s_P%5B%22Kubernetes%20%E3%83%AF%E3%83%BC%E3%82%AB%E3%83%BC%E3%83%8E%E3%83%BC%E3%83%89%22%5D%0A%20%20%20%20%20%20%20%20PG_P%5B(%22PostgreSQL%2018.6%20Primary%22)%5D%0A%20%20%20%20%20%20%20%20Redis_P%5B(%22Redis%20Primary%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SecondaryDC%20%5B%22%E7%81%BD%E5%AE%B3%E5%BE%A9%E6%97%A7%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%20(Standby)%22%5D%0A%20%20%20%20%20%20%20%20K8s_S%5B%22Kubernetes%20%E5%BE%85%E6%A9%9F%E3%83%8E%E3%83%BC%E3%83%89%22%5D%0A%20%20%20%20%20%20%20%20PG_S%5B(%22PostgreSQL%2018.6%20Standby%22)%5D%0A%20%20%20%20%20%20%20%20Redis_S%5B(%22Redis%20Replica%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20GSLB%5B%22GSLB%20%2F%20DNS%20%E3%83%88%E3%83%A9%E3%83%95%E3%82%A3%E3%83%83%E3%82%AF%E3%83%AB%E3%83%BC%E3%82%BF%E3%83%BC%22%5D%20--%3E%20PrimaryDC%0A%20%20%20%20GSLB%20-.-%3E%20%7C%E9%9A%9C%E5%AE%B3%E7%99%BA%E7%94%9F%E6%99%82%E3%81%AB15%E5%88%86%E4%BB%A5%E5%86%85%E3%81%A7%E5%88%87%E3%82%8A%E6%9B%BF%E3%81%88%7C%20SecondaryDC%0A%20%20%20%20%0A%20%20%20%20PG_P%20--%3E%20%7C%E5%90%8C%E6%9C%9FWAL%E3%82%B9%E3%83%88%E3%83%AA%E3%83%BC%E3%83%9F%E3%83%B3%E3%82%B0%E3%83%AC%E3%83%97%E3%83%AA%E3%82%B1%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%7C%20PG_S%0A%20%20%20%20Redis_P%20--%3E%20%7C%E9%9D%9E%E5%90%8C%E6%9C%9F%E3%83%A1%E3%83%A2%E3%83%AA%E3%83%AC%E3%83%97%E3%83%AA%E3%82%B1%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%7C%20Redis_S%0A"})]),fallback:s(()=>[...i[0]||(i[0]=[h(" Loading... ",-1)])]),_:1})),i[2]||(i[2]=e(`<hr><h2 id="_2-データ層の高可用性およびレプリケーションアーキテクチャ" tabindex="-1">2. データ層の高可用性およびレプリケーションアーキテクチャ <a class="header-anchor" href="#_2-データ層の高可用性およびレプリケーションアーキテクチャ" aria-label="Permalink to “2. データ層の高可用性およびレプリケーションアーキテクチャ”">​</a></h2><h3 id="_1-postgresql-18-6-pgvector-walストリーミングレプリケーション" tabindex="-1">1) PostgreSQL 18.6（pgvector）WALストリーミングレプリケーション <a class="header-anchor" href="#_1-postgresql-18-6-pgvector-walストリーミングレプリケーション" aria-label="Permalink to “1) PostgreSQL 18.6（pgvector）WALストリーミングレプリケーション”">​</a></h3><ul><li>ビジネステーブルおよびAI埋め込みベクトルデータの一貫性を維持するため、PostgreSQL 18.6の物理ストリーミングレプリケーション（Physical Streaming Replication）を適用します。</li><li><code>synchronous_commit = on</code> 設定により、トランザクションコミット信号が待機ノードのWAL（Write-Ahead Log）に記録された後に最終的なクライアント応答を返却し、障害発生時のコミット欠損を防止します。</li></ul><div class="language-ini"><button title="コードをコピー" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># postgresql.conf (Primary)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">wal_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = replica</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_wal_senders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">wal_keep_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 4096MB</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronous_commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = on</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronous_standby_names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;FIRST 1 (dr_standby_node)&#39;</span></span></code></pre></div><h3 id="_2-ポイントインタイムリカバリ-pitr-point-in-time-recovery-パイプライン" tabindex="-1">2) ポイントインタイムリカバリ（PITR: Point-In-Time Recovery）パイプライン <a class="header-anchor" href="#_2-ポイントインタイムリカバリ-pitr-point-in-time-recovery-パイプライン" aria-label="Permalink to “2) ポイントインタイムリカバリ（PITR: Point-In-Time Recovery）パイプライン”">​</a></h3><ul><li>毎日02:00にベースバックアップ（Base Backup）をMinIOオブジェクトストレージへ圧縮・暗号化して格納します。</li><li>継続的に生成されるWALアーカイブファイルは60秒周期で待機ストレージへ同期され、管理者の誤操作によるデータ汚染が発生した際、特定の分・秒単位でデータベースを精密に復元できるPITR環境を提供します。</li></ul><hr><h2 id="_3-redis分散ロックおよびセッションレプリケーション" tabindex="-1">3. Redis分散ロックおよびセッションレプリケーション <a class="header-anchor" href="#_3-redis分散ロックおよびセッションレプリケーション" aria-label="Permalink to “3. Redis分散ロックおよびセッションレプリケーション”">​</a></h2><ul><li>エージェント間の同時タスク競合を防止する分散ロック（Redlock）およびアクティブユーザーセッションは、Redis Sentinelベースの3ノード自動フェイルオーバークラスタとして構成されます。</li><li>マスターノードに深刻なハードウェア障害が発生した場合、Sentinelクオーラム（Quorum）合意により3秒以内にレプリカノードが新しいマスターへ自動昇格します。</li></ul><hr><h2 id="_4-災害発生時の段階別フェイルオーバー手順" tabindex="-1">4. 災害発生時の段階別フェイルオーバー手順 <a class="header-anchor" href="#_4-災害発生時の段階別フェイルオーバー手順" aria-label="Permalink to “4. 災害発生時の段階別フェイルオーバー手順”">​</a></h2><p>主データセンターの物理的浸水、停電、または通信回線断絶事故が発生した場合、以下の標準運用手順（SOP）に従って待機センターへ切り替えます。</p><ol><li><strong>状態検知および障害宣言（0〜3分）</strong>: <ul><li>外部ヘルスチェックプローブ3拠点において、主センターの5xxエラーまたは無応答が180秒以上継続した場合、インフラ危機アラートを発報します。</li></ul></li><li><strong>待機データベースの昇格（3〜7分）</strong>: <ul><li>災害復旧センターのPostgreSQL Standbyノードで昇格コマンドを実行し、読み取り／書き込みモードへ切り替えます。<div class="language-bash"><button title="コードをコピー" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_ctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> promote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/postgresql/data</span></span></code></pre></div></li></ul></li><li><strong>Kubernetes Podのスケールアウトおよび起動（7〜10分）</strong>: <ul><li>待機クラスタのドメインエージェントDeploymentレプリカ数を、平時の待機状態（1台）から本番稼働仕様（最小3台以上）へ即座にスケールアウトします。</li></ul></li><li><strong>GSLBトラフィックの切り替え（10〜15分）</strong>: <ul><li>グローバルサーバーロードバランサー（GSLB）の重み付けを主センター0%、待機センター100%に切り替え、DNS TTL（60秒）の満了を待機します。</li><li>サービスの正常流入および認可トークンセッションの正常検証可否を最終確認します。</li></ul></li></ol><hr><h2 id="_5-定期模擬訓練および復旧検証" tabindex="-1">5. 定期模擬訓練および復旧検証 <a class="header-anchor" href="#_5-定期模擬訓練および復旧検証" aria-label="Permalink to “5. 定期模擬訓練および復旧検証”">​</a></h2><ul><li><strong>訓練周期</strong>: 四半期に1回、定期DR模擬訓練を実施します。</li><li><strong>検証項目</strong>: <ul><li>実際の主センターネットワークインターフェースを強制遮断した後のトラフィック切り替え完了時間の計測。</li><li>切り替え完了後、エージェント作業履歴およびRAGベクトルインデックスのデータ欠損（0件）の全数照合。</li><li>模擬訓練結果レポートを作成し、エンタープライズコンプライアンス監査証跡として保管。</li></ul></li></ul>`,17))])}const u=l(p,[["render",c]]);export{m as __pageData,u as default};
